// The public export's identity is CONDITIONAL, so the package's public
// surface does not statically prove what `vulnerable` names. That must
// fail closed to UNKNOWN -- and specifically must NOT be "recovered" by
// looking at the same-named sibling in other.js.
var impl = require("./impl");

if (process.env.AUTHORITATIVE_PUBLIC_ENTRY_MODE === "dangerous") {
  exports.vulnerable = impl.dangerousImpl;
}

exports.runOther = require("./other").vulnerable;
